import net from 'net';

const MAX_PORT = 65535;

function isPortInUse(port: number): Promise<boolean> {
  function checkHost(host: string): Promise<boolean> {
    return new Promise((resolve) => {
      const socket = net.connect(port, host);
      socket.setTimeout(300);
      socket.on('connect', () => {
        socket.destroy();
        resolve(true);
      });
      socket.on('error', () => {
        socket.destroy();
        resolve(false);
      });
      socket.on('timeout', () => {
        socket.destroy();
        resolve(false);
      });
    });
  }
  return Promise.all([checkHost('127.0.0.1'), checkHost('::1')]).then(
    ([v4, v6]) => v4 || v6,
  );
}

export async function findAvailablePort(startPort: number): Promise<number> {
  if (startPort > MAX_PORT) {
    throw new Error(`No available port found up to ${MAX_PORT}`);
  }

  const bindable = await new Promise<boolean>((resolve) => {
    const server = net.createServer();
    server.listen(startPort, () => {
      server.close(() => resolve(true));
    });
    server.on('error', () => resolve(false));
  });

  if (!bindable || (await isPortInUse(startPort))) {
    return findAvailablePort(startPort + 1);
  }

  return startPort;
}

const LOOPBACK_PROBE_HOSTS = ['localhost', '127.0.0.1', '[::1]'] as const;

export async function probeLoopbackHttp(
  port: number,
  options?: {
    method?: string;
    timeoutMs?: number;
    acceptServerErrors?: boolean;
  },
): Promise<boolean> {
  const method = options?.method ?? 'HEAD';
  const timeoutMs = options?.timeoutMs ?? 1200;
  for (const host of LOOPBACK_PROBE_HOSTS) {
    try {
      const response = await fetch(`http://${host}:${port}`, {
        method,
        signal: AbortSignal.timeout(timeoutMs),
      });
      if (options?.acceptServerErrors || response.status < 500) {
        return true;
      }
    } catch {
    }
  }
  return false;
}
